def solution(data):
    df_sales = next((df for n, df in data.items() if 'So_chi_tiet_ban_hang' in n), None)
    if df_sales is None:
        raise DataNotFoundError("Không tìm thấy dữ liệu bán hàng phù hợp", table_name="bán hàng")

    cols = df_sales.columns.tolist()
    date_col = next((c for c in cols if any(k in str(c).lower() for k in ['ngày', 'date', 'thời gian'])), None)
    if date_col is None:
        raise DataNotFoundError("Không tìm thấy cột ngày trong bảng bán hàng")

    df_sales['clean_date'] = clean_date(df_sales[date_col])
    mask = (df_sales['clean_date'].dt.year == 2025) & (df_sales['clean_date'].dt.month == 7)
    df_period = df_sales[mask]

    if df_period.empty:
        return 0

    prod_col = next((c for c in cols if any(k in str(c).lower() for k in ['tên hàng', 'sản phẩm', 'mặt hàng', 'tên thuốc', 'hàng'])), None)
    if prod_col is None:
        raise DataNotFoundError("Không tìm thấy cột tên hàng trong bảng bán hàng")

    grp = df_period.groupby(prod_col, as_index=False)['clean_date'].count()
    result = grp[grp['clean_date'] >= 74]['clean_date'].sum()
    return int(round(result))
